#!/usr/bin/env python3
"""Generate SEO-friendly static HTML from Decap-managed JSON. No pip dependencies."""
import json,html,re
from pathlib import Path
root=Path(__file__).resolve().parents[1]
def load(n):return json.loads((root/'content'/n).read_text())
def esc(x):return html.escape(str(x or ''),quote=True)
def url(x):
 x=str(x or '').strip()
 return esc(x) if x.startswith(('https://','http://','mailto:','/','assets/','#')) else '#'
def vid(x,large=False):
 id=str(x.get('vimeo_id',''));id=id if re.fullmatch(r'\d+',id) else '0'
 title=esc(x.get('title','Vimeo video'));start=int(x.get('start_at') or 0)
 return f'<div class="video-frame"><button class="video-launch" type="button" data-vimeo-id="{id}" data-title="{title}" data-start="{start}" aria-label="Play {title}">{"Play reel" if large else "Play video"}</button></div>'
s=load('settings.json');projects=sorted((p for p in load('projects.json')['projects'] if p.get('visible',True)),key=lambda p:p.get('order',0));videos=sorted((v for v in load('videos.json')['videos'] if v.get('visible',True)),key=lambda v:v.get('order',0))
nav=[('hero','Home'),('reel','Reel'),('portfolio','Work'),('graphic','Directing'),('about','About'),('contact-form','Contact')]
nav_html=''.join(f'<li><a href="#{id}">{label}</a></li>' for id,label in nav)
project_html=''.join(f'<figure class="gallery-item" data-category="{esc(p["category"])}"><a data-lightbox href="{url(p["image"])}" aria-label="View {esc(p["title"])} poster"><img src="{url(p["image"])}" alt="{esc(p.get("alt") or p["title"])}" loading="lazy" decoding="async"></a><figcaption>{esc(p["title"])}</figcaption></figure>' for p in projects)
groups=''.join(f'<section class="directing-group"><h3>{esc(group)}</h3><div class="video-grid">'+''.join(f'<article>{vid(v)}<p class="video-caption">{esc(v["title"])}</p></article>' for v in videos if v.get('category')==group)+'</div></section>' for group in ('Short Films','Music Videos','Graphic Work') if any(v.get('category')==group for v in videos))
bio=''.join(f'<p>{esc(p)}</p>' for p in s['bio_paragraphs']);awards=''.join(f'<img src="{url(a)}" alt="Film award laurel" loading="lazy">' for a in s['award_images'])
canonical=url(s['canonical_url']);gtm=re.sub(r'[^A-Z0-9-]','',s.get('gtm_id',''))
tracking=f'<script async src="https://www.googletagmanager.com/gtm.js?id={gtm}"></script>' if gtm else ''
html_out=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(s['site_title'])}</title><meta name="description" content="{esc(s['site_description'])}"><link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:title" content="{esc(s['site_title'])}"><meta property="og:description" content="{esc(s['site_description'])}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{url(s['hero_desktop'])}"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Bebas+Neue&family=Rubik:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="/assets/css/style.css">{tracking}<script src="/assets/js/main.js" defer></script></head><body><a class="skip-link" href="#main">Skip to content</a><header id="header"><div class="container header-inner"><a href="#hero" class="brand"><strong>{esc(s['name'])}</strong><span>{esc(s['subtitle'])}</span><span>{esc(s['credentials'])}</span></a><nav aria-label="Main navigation"><button class="nav-toggle" aria-expanded="false" aria-controls="main-nav" type="button">Menu ☰</button><ul id="main-nav" class="nav-list">{nav_html}<li><a href="{url(s['imdb_url'])}" target="_blank" rel="noopener noreferrer">IMDb</a></li><li><a href="mailto:{esc(s['email'])}">Email</a></li></ul></nav></div></header><main id="main"><section id="hero" class="hero" aria-label="Homepage background"></section><style>.hero{{background-image:url('{url(s['hero_desktop'])}')}}@media(max-width:650px){{.hero{{background-image:url('{url(s['hero_mobile'])}')}}}}</style><section id="reel" class="section reel"><div class="container"><h2>{esc(s['reel_heading'])}</h2>{vid({'vimeo_id':s['reel_vimeo_id'],'title':'Editing reel'},True)}</div></section><section id="portfolio" class="section"><div class="wide"><h2>{esc(s['work_heading'])}</h2><div class="filter-bar" role="group" aria-label="Filter editing work"><button type="button" data-filter="all" aria-pressed="true">All</button><button type="button" data-filter="scripted" aria-pressed="false">Scripted</button><button type="button" data-filter="documentary" aria-pressed="false">Documentary</button></div><div class="gallery">{project_html}</div></div></section><section id="graphic" class="section"><div class="container"><h2>{esc(s['directing_heading'])}</h2>{groups}</div></section><section id="about" class="section"><div class="container"><h2>{esc(s['about_heading'])}</h2><div class="about-grid"><div><img class="portrait" src="{url(s['portrait'])}" alt="Portrait of {esc(s['name'])}" loading="lazy"></div><div class="bio">{bio}<a class="cv-link" href="{url(s['cv_url'])}" target="_blank" rel="noopener noreferrer">Download CV</a><div class="awards">{awards}</div></div></div></div></section><div class="contact-banner" role="img" aria-label="Editing studio" style="background-image:url('{url(s['contact_banner'])}')"></div><section id="contact-form" class="section"><div class="container contact-grid"><div><h2>{esc(s['contact_heading'])}</h2><form class="contact-form" action="{url(s['form_action'])}" method="POST"><label for="contact-name">Your Name</label><input id="contact-name" name="name" autocomplete="name" required><label for="contact-email">Email Address</label><input id="contact-email" type="email" name="email" autocomplete="email" required><label for="contact-message">Your Message</label><textarea id="contact-message" name="message" rows="5" required></textarea><button type="submit">Send Message</button></form></div><div><a class="instagram-link" href="{url(s['instagram_url'])}" target="_blank" rel="noopener noreferrer">View on Instagram</a></div></div></section></main><footer><div class="container"><ul class="socials"><li><a href="{url(s['imdb_url'])}" target="_blank" rel="noopener noreferrer">IMDb</a></li><li><a href="{url(s['vimeo_url'])}" target="_blank" rel="noopener noreferrer">Vimeo</a></li><li><a href="{url(s['linkedin_url'])}" target="_blank" rel="noopener noreferrer">LinkedIn</a></li><li><a href="mailto:{esc(s['email'])}">Email</a></li></ul></div></footer><div class="sub-footer"><div class="container">Copyright © {__import__('datetime').date.today().year} All rights reserved <span>· Site made by <a href="{url(s['credit_url'])}" target="_blank" rel="noopener noreferrer">{esc(s['credit_name'])}</a></span></div></div><button class="back-top" type="button" aria-label="Back to top">↑</button><dialog class="lightbox" aria-label="Portfolio image"><button type="button" class="lightbox-close" aria-label="Close image">✕</button><img alt=""></dialog></body></html>'''
(root/'index.html').write_text(html_out)
print(f'Built index.html with {len(projects)} projects and {len(videos)} videos')
